@Component("location-entity-projector")
public class LocationEntityProjector implements EntityProjector<Location>{
		
	// core constructor
	public LocationEntityProjector(ProjectorRegistry registry,
										LocationRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Location> getEntityClass() {
		return Location.class;
	}

    /*
	 * Insert a Location
	 * 
     * @param	entity Location
     */
    public Location create( Location entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Location
	 * 
     * @param	entity Location
     */
    public Location update( Location entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Location
	 * 
     * @param	id		UUID
     */
    public Location delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Location entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Warehouse
     * 
     * @param	parentId	UUID
     * @param	assignment 	Warehouse 
     * @return	Location
     */
    public Location assignWarehouse( UUID parentId, Warehouse assignment ) {
	    LOGGER.info("assigning Warehouse as " + assignment.toString() );

	    Location parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Warehouse.class, assignment.getWarehouseId());

	    // ------------------------------------------
		// assign the Warehouse to the parent entity
		// ------------------------------------------ 
	    parentEntity.setWarehouse( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Warehouse
	 * 
	 * @param	parentId		UUID
	 * @return	Location
	 */
	public Location unAssignWarehouse( UUID parentId ) {
		Location parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Warehouse on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Warehouse on the parent entithy
		// ------------------------------------------     
	    parentEntity.setWarehouse(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the InventoryItems
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Location
     */
    public Location addToInventoryItems( UUID parentId, InventoryItem addTo ) {
	    LOGGER.info("handling AssignInventoryItemsToLocationEvent - " );
	    
	    Location parentEntity = repository.findById(parentId).get();
	    InventoryItem child = registry.project( InventoryItem.class, addTo.getInventoryItemId());
	    
	    parentEntity.getInventoryItems().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the InventoryItems
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Location
     */
	public Location removeFromInventoryItems( UUID parentId, InventoryItem removeFrom ) {
	    LOGGER.info("handling RemoveInventoryItemsFromLocationEvent " );
	
	    Location parentEntity = repository.findById(parentId).get();
	    InventoryItem child = registry.project( InventoryItem.class, removeFrom.getInventoryItemId());
	    
	    parentEntity.getInventoryItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Location via an FindLocationQuery
     * @return 	query	FindLocationQuery
     */
    @SuppressWarnings("unused")
    public Location find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Location - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Locations
     *
     * @param	query	FindAllLocationQuery 
     * @return 	List<Location> 
     */
    @SuppressWarnings("unused")
    public List<Location> findAll( FindAllLocationQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Location - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final LocationRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(LocationEntityProjector.class.getName());

}
